-- Sprint 3: lavados, ventas, cobros y comisiones con precios históricos.
create table if not exists public.lavados (
  "Id_Lavados" integer generated by default as identity primary key,
  "Id_Vehiculos" integer not null references public.vehiculos("Id_Vehiculos") on delete restrict,
  "Sector" integer not null check ("Sector" between 1 and 10),
  "Fecha" timestamp not null,
  "FechaFinalizacion" timestamp null,
  "Estado" varchar(20) not null default 'Registrado' check ("Estado" in ('Registrado','Terminado','Cancelado')),
  "Id_Usuarios" integer not null references public.usuarios("Id_Usuarios"),
  "FechaAnulacion" timestamp null,
  "Id_Usuarios_Anulacion" integer null references public.usuarios("Id_Usuarios"),
  "MotivoAnulacion" varchar(250) null
);
create unique index if not exists ux_lavados_sector_fecha_activo on public.lavados("Sector","Fecha") where "Estado"='Registrado';
create table if not exists public.lavados_servicios (
  "Id_Lavados_Servicios" integer generated by default as identity primary key,
  "Id_Lavados" integer not null references public.lavados("Id_Lavados") on delete cascade,
  "Id_Productos" integer not null references public.productos("Id_Productos") on delete restrict,
  "PrecioAplicado" numeric(18,0) not null check ("PrecioAplicado">=0), "EsAdicional" boolean not null default false
);
create table if not exists public.lavados_participantes (
  "Id_Lavados" integer not null references public.lavados("Id_Lavados") on delete cascade,
  "Id_Personas" integer not null references public.personas("Id_Personas") on delete restrict,
  primary key("Id_Lavados","Id_Personas")
);
create table if not exists public.lavados_historial_estados (
  "Id_Lavados_Historial" integer generated by default as identity primary key,
  "Id_Lavados" integer not null references public.lavados("Id_Lavados") on delete cascade,
  "Estado" varchar(20) not null check ("Estado" in ('Registrado','Terminado','Cancelado')),
  "Fecha" timestamp not null default now(), "Id_Usuarios" integer not null references public.usuarios("Id_Usuarios")
);
create table if not exists public.ventas (
  "Id_Ventas" integer generated by default as identity primary key,
  "Id_Lavados" integer null references public.lavados("Id_Lavados") on delete restrict,
  "Fecha" timestamp not null default now(), "Condicion" varchar(10) not null check ("Condicion" in ('Contado','Crédito')),
  "Total" numeric(18,0) not null check("Total">=0), "Estado" varchar(20) not null default 'Registrada' check("Estado" in ('Registrada','Anulada')),
  "Id_Usuarios" integer not null references public.usuarios("Id_Usuarios"), "FechaAnulacion" timestamp null,
  "Id_Usuarios_Anulacion" integer null references public.usuarios("Id_Usuarios"), "MotivoAnulacion" varchar(250) null
);
create table if not exists public.ventas_detalle (
  "Id_Ventas_Detalle" integer generated by default as identity primary key,
  "Id_Ventas" integer not null references public.ventas("Id_Ventas") on delete cascade,
  "Id_Productos" integer not null references public.productos("Id_Productos") on delete restrict,
  "Cantidad" numeric(18,0) not null check("Cantidad">0), "PrecioUnitario" numeric(18,0) not null check("PrecioUnitario">=0), "Subtotal" numeric(18,0) not null check("Subtotal">=0)
);
create table if not exists public.cobros (
  "Id_Cobros" integer generated by default as identity primary key,
  "Id_Ventas" integer not null references public.ventas("Id_Ventas") on delete cascade,
  "Fecha" timestamp not null default now(), "MedioPago" varchar(20) not null check("MedioPago" in ('Efectivo','Débito','Crédito')),
  "Importe" numeric(18,0) not null check("Importe">0), "Id_Usuarios" integer not null references public.usuarios("Id_Usuarios")
);
create table if not exists public.configuracion_comision (
  "Id_Configuracion_Comision" integer primary key check ("Id_Configuracion_Comision" = 1),
  "Porcentaje" numeric(5,2) not null default 30 check("Porcentaje" between 0 and 100),
  "FechaActualizacion" timestamp not null default now(), "Id_Usuarios" integer not null references public.usuarios("Id_Usuarios")
);
insert into public.configuracion_comision("Id_Configuracion_Comision","Porcentaje","FechaActualizacion","Id_Usuarios")
select 1,30,now(),"Id_Usuarios" from public.usuarios order by "Id_Usuarios" limit 1
on conflict do nothing;
create table if not exists public.comisiones (
  "Id_Comisiones" integer generated by default as identity primary key,
  "Id_Ventas" integer not null references public.ventas("Id_Ventas") on delete cascade,
  "Id_Personas" integer not null references public.personas("Id_Personas") on delete restrict,
  "PorcentajeAplicado" numeric(5,2) not null check("PorcentajeAplicado" between 0 and 100), "Importe" numeric(18,2) not null check("Importe">=0), "Anulada" boolean not null default false
);
alter table public.lavados enable row level security;
alter table public.lavados_servicios enable row level security;
alter table public.lavados_participantes enable row level security;
alter table public.lavados_historial_estados enable row level security;
alter table public.ventas enable row level security;
alter table public.ventas_detalle enable row level security;
alter table public.cobros enable row level security;
alter table public.configuracion_comision enable row level security;
alter table public.comisiones enable row level security;
